definition:
name: showcase-gtm-agent-on-release
description: When a release ships, hand its notes to the GTM agent for positioning and launch angles
maxRunCostUsd: 1.5
on:
  webhook: {}
do:
  - id: release
    script.run:
      input: { repo: "tangle-network/agent-runtime" }
      egress: { allowDomains: [api.github.com] }
      timeoutMs: 60000
      source: |
        export default async function run(input: { repo: string }) {
          const res = await fetch("https://api.github.com/repos/" + input.repo + "/releases/latest", { headers: { accept: "application/vnd.github+json", "user-agent": "tangle-workflow" } });
          if (!res.ok) throw new Error("GitHub releases returned " + res.status);
          const r = await res.json();
          const notes = String(r.body || "").replace(/ by @[A-Za-z0-9-]+/g, "");
          console.log(r.tag_name + " published " + r.published_at + "\n" + notes);
          return { repo: input.repo, tag: r.tag_name, publishedAt: r.published_at, url: r.html_url, notes };
        }
  - id: gtm
    needs: [release]
    agent.run:
      profile: gtm
      timeout: 15m
      prompt: |
        A release just shipped: ${steps.release.tag} of ${steps.release.repo} (${steps.release.url}).

        Notes:
        ${truncate(steps.release.notes, 4000)}

        Work from these notes and the public repository only; take no external action and post nothing.
        Return, in under 250 words: who this release matters to (one ICP line), the single strongest launch angle,
        three one-line message variants for developers, and one metric to watch after launch.
